def get_os_group(name: _STR_OR_INT_OR_NONE = None) -> grp.struct_group:
    """Get an operating system group object.

    This function retrieves information about a group on the operating system by either its name or GID (Group ID). If no specific group is provided, it defaults to the current user's primary group.

    Args:
        name (:obj:`str` or :obj:`int`, optional): The "group name" or ``gid`` of the group. Defaults to the current user's primary group if not specified.

    Raises:
        OSError: If the given ``name`` does not exist as a "group name" for this operating system and is not an integer GID that exists on the system.

    Returns:
        :obj:`struct_group <grp>`: A tuple-like object containing group information, including the group name, password, group ID, and member list.

    Example:
        >>> from flutils.pathutils import get_os_group
        >>> get_os_group('bar')
        grp.struct_group(gr_name='bar', gr_passwd='*', gr_gid=2001, gr_mem=['foo'])
    """
    if name is None:
        name = get_os_user().pw_gid
        name = cast(int, name)
    if isinstance(name, int):
        try:
            return grp.getgrgid(name)
        except KeyError:
            raise OSError(
                'The given gid: %r, is not a valid gid for this operating '
                'system.' % name
            )
    try:
        return grp.getgrnam(name)
    except KeyError:
        raise OSError(
            'The given name: %r, is not a valid "group name" '
            'for this operating system.' % name
