class _CherryPickingModule:
    'A module that manages attributes pointing to lazy-loaded-modules\n    and lazy-loaded-module-attributes.\n    '
    def __getattribute__(self, attr: str) -> Any:
        """
        A module that manages attributes pointing to lazy-loaded modules and lazy-loaded module attributes.

        This class uses a special dictionary `__cherry_pick_map__` to map attribute names to their corresponding module names. When an attribute is accessed, the `__getattribute__` method checks if it is in the `__cherry_pick_map__`. If it is, and the attribute has not been initialized yet (`_CHERRY_PICK`), the method imports the specified module and assigns the requested attribute or module to the instance.

        Parameters:
            attr (str): The name of the attribute being accessed. This parameter is automatically provided by Python when accessing attributes dynamically.

        Returns:
            Any: The value of the accessed attribute, which may be a lazy-loaded module or attribute.

        Example:
            To use this class, you would typically subclass it and define your own `__cherry_pick_map__` dictionary within that subclass to specify how attributes should be mapped to modules and their respective attributes. For example:

            ```python
            class MyModule(_CherryPickingModule):
                def __init__(self):
                    self.__cherry_pick_map__ = {
                        'my_attribute': 'mymodule',
                    }

            my_instance = MyModule()
            print(my_instance.my_attribute)  # This will import the module "mymodule" and assign its attribute to "my_attribute" in the instance.
            ```

        In this example, `__cherry_pick_map__` is a dictionary where keys are attribute names and values are module names. When `my_attribute` is accessed on an instance of `MyModule`, the method will import the module named "mymodule" and assign its attribute to `my_attribute`.
        """
        _dict_ = object.__getattribute__(self, '__dict__')
        _cherry_pick_map_: _CherryPickMap = _dict_.get(
            '__cherry_pick_map__',
            _EMPTY_CHERRY_PICK_MAP
        )
        if attr in _cherry_pick_map_.identifiers:
            if _dict_[attr] == _CHERRY_PICK:
                mod_name = _cherry_pick_map_.identifiers[attr]
                module = importlib.import_module(mod_name)
                for attr_mapping in _cherry_pick_map_.modules[mod_name]:
                    if attr_mapping.mod_attr_name:
                        object.__setattr__(
                            self,
                            attr_mapping.attr_name,
                            getattr(module, attr_mapping.mod_attr_name)
                        )
                    else:
                        object.__setattr__(
                            self,
                            attr_mapping.attr_name,
                            module
                        )
        return object.__getattribute__(self, attr)
```

